function search(table, x) {
  var l = 0, h = table.length;

  if (table.length == 0 || x <= table[0]) {
    return -1;
  }

  while (l + 1 < h) {
    var pivot = (l + h + 1) / 2;
    if (table[pivot] < x) {
      l = pivot;
    } else {
      h = pivot;
    }
  }
  return l;
}

